import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { MapContainer, TileLayer, CircleMarker, Popup, GeoJSON, useMap } from 'react-leaflet';
import { ResponsiveContainer, ComposedChart, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, PieChart, Pie, Cell, LineChart, Line, Legend, Treemap, AreaChart, Area, ScatterChart, Scatter, ZAxis, ReferenceLine } from 'recharts';
import { Activity, Map as MapIcon, ChartNoAxesColumn, Upload, House, Lightbulb, RotateCcw, Download, LogOut, Search, Filter, Play, Pause, Moon, Sun, ChevronRight, ShieldCheck, Hospital, BedDouble, MapPinned, FileSpreadsheet, AlertCircle, CheckCircle2, ArrowUpRight, Menu, X } from 'lucide-react';
import * as XLSX from 'xlsx';
import 'leaflet/dist/leaflet.css';
import './styles.css';

const API = import.meta.env.VITE_API_URL || '/api';
const COLORS = { government:'#0072B2', private:'#D55E00', aqua:'#56B4E9', gold:'#E69F00', purple:'#CC79A7', ink:'#0a2f3c' };
const TYPE_PALETTE=['#0072B2','#D55E00','#009E73','#CC79A7','#E69F00','#56B4E9','#6E6E6E','#332288','#AA4499','#117733','#88CCEE'];
const fmt = (n) => Number(n || 0).toLocaleString('en-IN');
const safe = (v) => String(v ?? '').trim() || 'Unspecified';
const bytesToHex = (bytes) => [...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('');
async function passwordHash(password,salt) {
  const key = await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);
  const bits = await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256);
  return bytesToHex(bits);
}

function App() {
  const [data,setData] = useState(null);
  const [page,setPage] = useState('home');
  const [user,setUser] = useState(()=>{ try { return JSON.parse(localStorage.getItem('udupi-health-session')||'null'); } catch { return null; } });
  const [signedIn,setSignedIn] = useState(()=>{ try { return Boolean(JSON.parse(localStorage.getItem('udupi-health-session')||'null')); } catch { return false; } });
  const [authMode,setAuthMode] = useState(()=>{ try { return localStorage.getItem('udupi-health-accounts') ? 'signin' : 'signup'; } catch { return 'signup'; } });
  const [loginName,setLoginName] = useState('');
  const [loginEmail,setLoginEmail] = useState('');
  const [loginPass,setLoginPass] = useState('');
  const [confirmPass,setConfirmPass] = useState('');
  const [loginError,setLoginError] = useState('');
  const [theme,setTheme] = useState('light');
  const [mobileNav,setMobileNav] = useState(false);
  const [taluk,setTaluk] = useState('all');
  const [ownership,setOwnership] = useState('all');
  const [facilityType,setFacilityType] = useState('all');
  const [search,setSearch] = useState('');
  const [uploadError,setUploadError] = useState('');
  const [uploadSuccess,setUploadSuccess] = useState('');
  const [busy,setBusy] = useState(false);
  const [metric,setMetric] = useState('Number of PW received 4 or more ANC check ups');
  const [yearIndex,setYearIndex] = useState(13);
  const [playing,setPlaying] = useState(false);
  const [selectedFacility,setSelectedFacility] = useState(null);
  const [mapBoundary,setMapBoundary] = useState(null);
  const [talukBoundary,setTalukBoundary] = useState(null);
  const [mapMode,setMapMode] = useState('facilities');
  const [selectedTaluk,setSelectedTaluk] = useState('');
  const [darkMap,setDarkMap] = useState(false);
  const [excelRows,setExcelRows] = useState([]);
  const [excelHeaders,setExcelHeaders] = useState([]);
  const [excelFileName,setExcelFileName] = useState('');
  const [excelX,setExcelX] = useState('');
  const [excelY,setExcelY] = useState('');
  const [excelChartType,setExcelChartType] = useState('bar');
  const [excelError,setExcelError] = useState('');

  async function loadData() {
    const response = await fetch(`${API}/data`);
    if (!response.ok) throw new Error('Could not load the Udupi dataset.');
    setData(await response.json());
  }
  useEffect(() => { loadData().catch(e=>setUploadError(e.message)); fetch('/atlas-data/udupi_district.geojson').then(r=>r.ok?r.json():null).then(setMapBoundary).catch(()=>{}); fetch('/atlas-data/udupi_taluks.geojson').then(r=>r.ok?r.json():null).then(setTalukBoundary).catch(()=>{}); },[]);
  useEffect(() => { document.documentElement.dataset.theme = theme; try { localStorage.setItem('au_theme',theme); } catch {} },[theme]);
  useEffect(() => {
    if (!playing) return;
    const id = setInterval(() => setYearIndex(v => { if (v >= (data?.years?.length || 14)-1) { setPlaying(false); return 0; } return v+1; }), 1100);
    return () => clearInterval(id);
  },[playing,data?.years?.length]);

  const facilities = data?.facilities || [];
  useEffect(() => { try { localStorage.setItem('udupi-active-facilities', JSON.stringify(facilities)); } catch {} },[facilities]);
  const taluks = useMemo(()=>[...new Set(facilities.map(f=>safe(f.taluk)))].sort(),[facilities]);
  const types = useMemo(()=>[...new Set(facilities.map(f=>safe(f.type)))].sort(),[facilities]);
  const facilityTypeColors=Object.fromEntries(types.map((type,i)=>[type,TYPE_PALETTE[i%TYPE_PALETTE.length]]));
  const filtered = useMemo(()=>facilities.filter(f=>(taluk==='all'||f.taluk===taluk)&&(ownership==='all'||f.ownership===ownership)&&(facilityType==='all'||f.type===facilityType)&&(!search||`${f.name} ${f.taluk} ${f.type}`.toLowerCase().includes(search.toLowerCase()))),[facilities,taluk,ownership,facilityType,search]);
  const activeFacilityTypes=[...new Set(filtered.map(f=>safe(f.type)))].sort();
  const bedTotal = filtered.reduce((sum,f)=>sum+(Number(f.beds)||0),0);
  const governmentBeds = filtered.filter(f=>f.ownership==='Government').reduce((s,f)=>s+(Number(f.beds)||0),0);
  const privateBeds = filtered.filter(f=>f.ownership==='Private').reduce((s,f)=>s+(Number(f.beds)||0),0);
  const ownershipData = [{name:'Government',value:filtered.filter(f=>f.ownership==='Government').length,color:COLORS.government},{name:'Private',value:filtered.filter(f=>f.ownership==='Private').length,color:COLORS.private},{name:'Other',value:filtered.filter(f=>!['Government','Private'].includes(f.ownership)).length,color:COLORS.purple}].filter(x=>x.value>0);
  const talukData = taluks.map(t=>{ const fs=filtered.filter(f=>f.taluk===t); return {taluk:t,facilities:fs.length,beds:fs.reduce((s,f)=>s+(Number(f.beds)||0),0)}; }).filter(x=>x.facilities);
  const capacityBalance = talukData.map(t=>({...t,facilityShare:filtered.length?t.facilities/filtered.length*100:0,bedShare:bedTotal?t.beds/bedTotal*100:0})).map(t=>({...t,gap:t.bedShare-t.facilityShare})).sort((a,b)=>a.gap-b.gap);
  const leadingFacilityTaluk=[...talukData].sort((a,b)=>b.facilities-a.facilities)[0];
  const topFacilityTaluks=[...talukData].sort((a,b)=>b.facilities-a.facilities).slice(0,5);
  const largestShareGap=bedTotal?[...capacityBalance].sort((a,b)=>Math.abs(b.gap)-Math.abs(a.gap))[0]:null;
  
  let cumulativeBeds=0;
  const capacityPareto=[...filtered].filter(f=>Number(f.beds)>0).sort((a,b)=>Number(b.beds)-Number(a.beds)).slice(0,15).map(f=>{cumulativeBeds+=Number(f.beds);return {name:f.name.length>18?f.name.slice(0,16)+'…':f.name,beds:Number(f.beds),cumulativeShare:bedTotal?cumulativeBeds/bedTotal*100:0,ownership:f.ownership};});
  const densityCells = useMemo(()=>{const cells=new Map();filtered.forEach(f=>{const lat=Number(f.lat),lon=Number(f.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon)||lat<-90||lat>90||lon<-180||lon>180)return;const row=Math.floor(lat/.035),col=Math.floor(lon/.045),key=row+':'+col;if(!cells.has(key))cells.set(key,{row,col,count:0,latSum:0,lonSum:0,beds:0,government:0,private:0,other:0});const c=cells.get(key);c.count++;c.latSum+=lat;c.lonSum+=lon;c.beds+=Number(f.beds)||0;if(f.ownership==='Private')c.private++;else if(f.ownership==='Government')c.government++;else c.other++;});return [...cells.values()].map(c=>({...c,lat:c.latSum/c.count,lon:c.lonSum/c.count}));},[filtered]);
  const densityMax=Math.max(1,...densityCells.map(c=>c.count));
  const talukStats=Object.fromEntries(capacityBalance.map(t=>[t.taluk,t]));
  const balanceExtent = Math.max(5,...capacityBalance.map(t=>Math.abs(t.gap)));
  const topFacilities = [...filtered].sort((a,b)=>(Number(b.beds)||0)-(Number(a.beds)||0)).slice(0,10).map(f=>({...f,shortName:f.name.length>22?f.name.slice(0,20)+'…':f.name}));
  const history = data?.history || {};
  const years = data?.years || [];
  const metricNames = Object.keys(history).filter(name=>years.some(y=>history[name]?.[y]?.value!==null&&history[name]?.[y]?.value!==undefined)).sort();
  const activeMetric = history[metric] || {};
  const trendData = years.map(y=>({year:y,value:activeMetric[y]?.value ?? null,records:activeMetric[y]?.records ?? 0}));
  const currentTrend = trendData[yearIndex];
  const facilityShare = filtered.length ? (filtered.filter(f=>f.ownership==='Government').length/filtered.length*100) : 0;
  const privateBedShare = bedTotal ? privateBeds/bedTotal*100 : 0;
  const sourceLabel = data?.datasetSource==='upload'?'Uploaded dataset':'Original Udupi sample';
  const metricByText = (text) => metricNames.find(name => name.toLowerCase().includes(text.toLowerCase()));
  const valueFor = (text, year) => { const name=metricByText(text); const value=name?history[name]?.[year]?.value:null; return value===null||value===undefined||!Number.isFinite(Number(value))?null:Number(value); };
  const latestYear=years[years.length-1]||'';
  const outpatientMix=Object.keys(history).filter(name=>name.startsWith('Outpatient - ')).map(name=>({name:name.replace('Outpatient - ',''),value:history[name]?.[latestYear]?.value??null})).filter(item=>Number.isFinite(Number(item.value))&&Number(item.value)>0).sort((a,b)=>Number(b.value)-Number(a.value));
  const outpatientTrend=years.map(year=>({year,diabetes:valueFor('Outpatient - Diabetes',year),hypertension:valueFor('Outpatient - Hypertension',year),mental:valueFor('Outpatient - Mental illness',year)}));
  const screeningTrend=years.map(year=>({year,young:valueFor('Number of children (6 month to 6 years) screened',year),school:valueFor('Number of children (6 years to 18 years) screened',year)}));
  const sessionTrend=years.map(year=>{const planned=valueFor('Immunisation sessions planned',year),held=valueFor('Immunisation sessions held',year);return {year,planned,held,completion:planned>0&&held!==null?held/planned*100:null};});
  const maternalSupport=[{name:'4+ ANC visits',match:'Number of PW received 4 or more ANC check ups'},{name:'Repeated Hb tests',match:'Number of PW tested for Haemoglobin'},{name:'JSSK medicines',match:'Number of Pregnant Women provided - Free Medicines'},{name:'JSSK free diet',match:'Number of Pregnant Women provided - Free Diet'},{name:'JSSK diagnostics',match:'Number of Pregnant Women provided - Free Diagnostics'}].map(item=>({name:item.name,value:valueFor(item.match,latestYear)})).filter(item=>item.value!==null&&item.value>0);
  const labTrend=years.map(year=>({year,labs:valueFor('Number of Lab Tests done',year),hb:valueFor('Number of Hb tests conducted',year)}));
  const emergencySeries=[{label:'Emergency registrations',match:'Patients registered at Emergency Department',color:COLORS.government},{label:'Trauma presentations',match:'Emergency - Trauma',color:COLORS.private},{label:'Acute cardiac emergencies',match:'Emergency - Acute Caridiac Emergencies',color:COLORS.gold},{label:'Obstetric complications',match:'Emergency - Obstetrics complications',color:COLORS.purple}];
  const emergencyIndex=years.map(year=>{const row={year};for(const series of emergencySeries){const vals=years.map(y=>valueFor(series.match,y)).filter(v=>v!==null);const base=vals[0],current=valueFor(series.match,year);row[series.label]=current!==null&&base>0?current/base*100:null;}return row;});
  const latestOPD=valueFor('Allopathic- Outpatient attendance',latestYear);
  const latestScreening=(valueFor('Number of children (6 month to 6 years) screened',latestYear)||0)+(valueFor('Number of children (6 years to 18 years) screened',latestYear)||0);
  const latestSessionRate=(()=>{const p=valueFor('Immunisation sessions planned',latestYear),h=valueFor('Immunisation sessions held',latestYear);return p>0&&h!==null?h/p*100:null;})();

  async function signIn(e) {
    e.preventDefault(); setLoginError('');
    const email=loginEmail.trim().toLowerCase();
    if (!/^\S+@\S+\.\S+$/.test(email)) { setLoginError('Enter a valid email address.'); return; }
    if (loginPass.length<8) { setLoginError('Use a password with at least 8 characters.'); return; }
    try {
      let accounts={}; try { accounts=JSON.parse(localStorage.getItem('udupi-health-accounts')||'{}'); } catch {}
      let account=accounts[email];
      if (authMode==='signup') {
        if (!loginName.trim()) { setLoginError('Enter your name.'); return; }
        if (loginPass!==confirmPass) { setLoginError('Passwords do not match.'); return; }
        if (account) { setLoginError('An account with this email already exists. Sign in instead.'); return; }
        const salt=bytesToHex(crypto.getRandomValues(new Uint8Array(16)));
        account={name:loginName.trim(),salt,hash:await passwordHash(loginPass,salt)};
        accounts[email]=account; localStorage.setItem('udupi-health-accounts',JSON.stringify(accounts));
      } else {
        if (!account || await passwordHash(loginPass,account.salt)!==account.hash) { setLoginError('Email or password is incorrect.'); return; }
      }
      const session={name:account.name,email}; localStorage.setItem('udupi-health-session',JSON.stringify(session));
      setUser(session); setSignedIn(true); setLoginPass(''); setConfirmPass(''); setPage('home');
    } catch { setLoginError('Account storage is unavailable in this browser. Enable local storage and try again.'); }
  }
  function signOut() { localStorage.removeItem('udupi-health-session'); setSignedIn(false); setUser(null); setPage('home'); setLoginPass(''); setConfirmPass(''); }
  async function uploadFile(file) {
    if (!file) return;
    setBusy(true); setUploadError(''); setUploadSuccess('');
    const form = new FormData(); form.append('dataset',file);
    try {
      const response = await fetch(`${API}/upload`,{method:'POST',body:form}); const result=await response.json();
      if (!response.ok) throw new Error(result.error || 'Upload failed.');
      await loadData(); setTaluk('all'); setOwnership('all'); setFacilityType('all'); setSearch(''); setUploadSuccess(result.message); setPage('upload');
    } catch(e) { setUploadError(e.message); } finally { setBusy(false); }
  }
  async function resetDataset() {
    setBusy(true); setUploadError(''); setUploadSuccess('');
    try { const response=await fetch(`${API}/reset`,{method:'POST'}); const result=await response.json(); if(!response.ok) throw new Error(result.error||'Reset failed.'); await loadData(); setTaluk('all');setOwnership('all');setFacilityType('all');setSearch('');setUploadSuccess(result.message); }
    catch(e){setUploadError(e.message);} finally{setBusy(false);}
  }
  function downloadTemplate() { window.location.href=`${API}/template`; }
  async function loadExcelForVisualisation(file) {
    if (!file) return;
    setExcelError(''); setExcelRows([]); setExcelHeaders([]); setExcelFileName(file.name);
    try {
      const bytes = await file.arrayBuffer();
      const workbook = XLSX.read(bytes, { type: 'array', cellDates: true });
      const sheet = workbook.Sheets[workbook.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(sheet, { defval: '' });
      if (!rows.length) throw new Error('This sheet has no data rows. Add a header row and data, then try again.');
      const headers = Object.keys(rows[0]);
      if (headers.length < 2) throw new Error('At least two columns are needed to create a chart.');
      setExcelRows(rows.slice(0, 5000)); setExcelHeaders(headers); setExcelX(headers[0]);
      const numeric = headers.find(h => rows.some(r => r[h] !== '' && Number.isFinite(Number(r[h]))));
      setExcelY(numeric || headers[1]);
    } catch (e) { setExcelError(e.message || 'Could not read this file. Try a valid CSV or Excel workbook.'); }
  }
  const excelChartData = useMemo(() => {
    if (!excelRows.length || !excelX || !excelY) return [];
    const grouped = new Map();
    excelRows.forEach((row, i) => {
      const label = String(row[excelX] ?? '').trim() || '(Blank)';
      const raw = row[excelY]; const value = typeof raw === 'number' ? raw : Number(String(raw).replace(/,/g, '').trim());
      if (!Number.isFinite(value)) return;
      const key = label;
      if (!grouped.has(key)) grouped.set(key, { label, value: 0, count: 0, rowIndex: i });
      const item = grouped.get(key); item.value += value; item.count += 1;
    });
    return [...grouped.values()].map(d => ({ ...d, value: Number((d.value / d.count).toFixed(2)) })).slice(0, 60);
  }, [excelRows, excelX, excelY]);
  function navTo(next) { setPage(next); setMobileNav(false); window.scrollTo({top:0,behavior:'smooth'}); }

  if (!signedIn) return (
    <div className="auth-screen">
      <div className="auth-orb orb-one"/><div className="auth-orb orb-two"/>
      <section className="auth-shell">
        <aside className="auth-visual">
          <div className="brand brand-light"><span className="brand-mark"><Activity size={21}/></span><span>Arogya Insights<small>UDUPI HEALTH ANALYTICS</small></span></div>
          <div className="auth-visual-copy"><span className="eyebrow light">UDUPI HEALTH ATLAS</span><h1>See the story<br/><em>behind the numbers.</em></h1><p>Facilities, capacity and district health trends in one clear view.</p></div>
          <div className="auth-mini-chart"><div className="mini-bars"><i/><i/><i/><i/><i/><i/><i/><i/></div><div className="mini-chart-label"><span>Facilities</span><span>Capacity</span><span>Trends</span></div></div>
        </aside>
        <form className="auth-form" onSubmit={signIn}>
          <div className="auth-topline"><span className="auth-mark"><Activity size={18}/> Arogya Insights</span><div className="auth-tabs"><button type="button" className={authMode==='signin'?'active':''} onClick={()=>{setAuthMode('signin');setLoginError('');}}>Sign in</button><button type="button" className={authMode==='signup'?'active':''} onClick={()=>{setAuthMode('signup');setLoginError('');}}>Create account</button></div></div>
          <h2>{authMode==='signup'?'Create your account':'Welcome back'}</h2><p className="muted">{authMode==='signup'?'Save your access on this browser.':'Sign in to continue your Udupi data story.'}</p>
          {authMode==='signup'&&<label className="field-label">Name<input value={loginName} onChange={e=>setLoginName(e.target.value)} placeholder="Your name" autoComplete="name" required/></label>}
          <label className="field-label">Email<input value={loginEmail} onChange={e=>setLoginEmail(e.target.value)} placeholder="you@example.com" type="email" autoComplete="email" required/></label>
          <label className="field-label">Password<input value={loginPass} onChange={e=>setLoginPass(e.target.value)} placeholder="At least 8 characters" type="password" autoComplete={authMode==='signup'?'new-password':'current-password'} required minLength={8}/></label>
          {authMode==='signup'&&<label className="field-label">Confirm password<input value={confirmPass} onChange={e=>setConfirmPass(e.target.value)} placeholder="Re-enter password" type="password" autoComplete="new-password" required minLength={8}/></label>}
          {loginError&&<div className="alert error"><AlertCircle size={16}/>{loginError}</div>}
          <button className="button primary full auth-submit" type="submit">{authMode==='signup'?'Create account':'Sign in'} <ChevronRight size={17}/></button>
          <small className="auth-storage-note">Saved locally in this browser</small>
        </form>
      </section>
    </div>
  );

  if (!data) return <div className="loading-screen"><div className="loader"/><p>Loading healthcare dataset…</p></div>;

  const navItems=[['home','Home',House],['map','Read the Map',MapIcon],['graphs','Read the Graphs',ChartNoAxesColumn],['upload','Upload Excel',Upload],['findings','Findings',Lightbulb]];
  return <div className="app-shell">
    <header className="topbar"><button className="mobile-menu" onClick={()=>setMobileNav(!mobileNav)} aria-label="Toggle navigation">{mobileNav?<X/>:<Menu/>}</button><button className="brand top-brand" onClick={()=>navTo('home')}><span className="brand-mark"><Activity size={19}/></span><span>Arogya Insights<small>UDUPI HEALTH ANALYTICS</small></span></button><nav className={`main-nav ${mobileNav?'open':''}`}>{navItems.map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>navTo(id)}><Icon size={16}/>{label}</button>)}</nav><div className="top-actions"><button className="icon-button" title="Toggle colour theme" onClick={()=>setTheme(theme==='light'?'dark':'light')}>{theme==='light'?<Moon size={17}/>:<Sun size={17}/>}</button><div className="user-chip"><span className="user-avatar">{(user?.name||user?.email||'A').slice(0,1).toUpperCase()}</span><span>{user?.name||user?.email||'Account'}</span></div><button className="icon-button" title="Sign out" onClick={signOut}><LogOut size={17}/></button></div></header>
    <main className="page-wrap">
      {page==='home'&&<>
        <section className="hero home-hero"><div className="hero-copy"><div className="eyebrow"><span className="status-dot"/> INTERACTIVE DATA STORY · UDUPI DISTRICT</div><h1>Healthcare,<br/><em>at a glance.</em></h1><p>Care, services and trends across Udupi.</p><div className="hero-actions"><button className="button primary" onClick={()=>navTo('map')}>Read the Map <ArrowUpRight size={17}/></button><button className="button secondary" onClick={()=>navTo('graphs')}>Read the Graphs <ChartNoAxesColumn size={17}/></button></div></div><div className="hero-visual"><div className="orbit orbit-a"/><div className="orbit orbit-b"/><div className="hero-visual-center"><Activity size={43}/><span>UDUPI</span><small>HEALTH DATA</small></div><div className="float-card float-one"><MapPinned size={18}/><span><b>{fmt(facilities.length)}</b><small>facilities listed</small></span></div><div className="float-card float-two"><BedDouble size={18}/><span><b>{fmt(facilities.reduce((s,f)=>s+(Number(f.beds)||0),0))}</b><small>listed beds</small></span></div></div></section>
        <section className="stats-grid"><Stat icon={Hospital} label="Facilities listed" value={fmt(facilities.length)} note="Healthcare locations in active data"/><Stat icon={BedDouble} label="Listed bed capacity" value={fmt(facilities.reduce((s,f)=>s+(Number(f.beds)||0),0))} note="Capacity values available in the data"/><Stat icon={MapPinned} label="Taluks represented" value={taluks.length} note="Distinct taluk labels in the dataset"/><Stat icon={Activity} label="Historical indicators" value={fmt(metricNames.length)} note={`${years.length} fiscal years available in source history`}/></section>
        <section className="section-block"><div className="section-heading"><div><span className="eyebrow">EXPLORE THE DATA</span><h2>Choose a view</h2></div><span className="source-pill"><span className="status-dot"/>{sourceLabel}</span></div><div className="feature-grid"><Feature icon={MapIcon} number="01" title="Read the Map" text="Locations and capacity" action="Open map" onClick={()=>navTo('map')}/><Feature icon={ChartNoAxesColumn} number="02" title="Read the Graphs" text="Services and trends" action="Explore charts" onClick={()=>navTo('graphs')}/><Feature icon={FileSpreadsheet} number="03" title="Upload Excel" text="Add a facility spreadsheet" action="Upload a dataset" onClick={()=>navTo('upload')}/></div></section>
        <section className="home-bottom"><div><span className="eyebrow light">FROM DATA TO DECISIONS</span><h2>Clear views.<br/>Better questions.</h2><p></p><button className="button white" onClick={()=>navTo('findings')}>View findings <ChevronRight size={17}/></button></div><div className="bottom-stat"><span>ACTIVE DATASET</span><b>{sourceLabel}</b><small>Last updated {data.lastUpdated?new Date(data.lastUpdated).toLocaleString(): 'during this session'}</small><button className="text-button" disabled={busy} onClick={resetDataset}><RotateCcw size={15}/> Restore original sample</button></div></section>
      </>}
      {page==='map'&&<>
        <PageIntro eyebrow="GEOGRAPHIC EXPLORER" title="Care across Udupi" subtitle="Explore facilities by location." source={sourceLabel}/>
        <FilterBar taluks={taluks} types={types} taluk={taluk} setTaluk={setTaluk} ownership={ownership} setOwnership={setOwnership} facilityType={facilityType} setFacilityType={setFacilityType} search={search} setSearch={setSearch} reset={()=>{setTaluk('all');setOwnership('all');setFacilityType('all');setSearch('');}}/>
        <div className="map-mode-tabs" role="group" aria-label="Map visualization"><button className={mapMode==='facilities'?'active':''} onClick={()=>setMapMode('facilities')}><MapPinned size={16}/> Facility locations</button><button className={mapMode==='density'?'active':''} onClick={()=>setMapMode('density')}><Activity size={16}/> Density clusters</button><button className={mapMode==='balance'?'active':''} onClick={()=>setMapMode('balance')}><BedDouble size={16}/> Taluk bed balance</button></div><div className="map-layout"><section className="map-card"><div className="map-card-head"><div><h3>{mapMode==='density'?"Facility density clusters":mapMode==='balance'?"Bed-share balance by taluk":"Udupi district facility map"}</h3><p>{fmt(filtered.length)} locations</p></div></div><div className="map-visual-legend">{mapMode==='balance'?<><span><i className="legend-dot priv"/>Fewer beds than facility share</span><span><i className="legend-dot balance"/>Similar shares</span><span><i className="legend-dot gov"/>More beds than facility share</span></>:mapMode==='density'?<><span><i className="legend-dot gov"/>Government-majority cell</span><span><i className="legend-dot priv"/>Private-majority cell</span><span><i className="legend-dot other"/>Other ownership</span><span>Bubble size = facility count</span></>:<><span><i className="legend-dot gov"/>Government</span><span><i className="legend-dot priv"/>Private</span><span><i className="legend-dot other"/>Other</span><span><i className="legend-size"/>Marker size = beds</span></>}</div><div className="map-frame"><MapContainer center={[13.45,74.78]} zoom={10} scrollWheelZoom className="leaflet-map" key={`${darkMap}-${mapBoundary?'boundary':'no-boundary'}`}><TileLayer attribution='&copy; OpenStreetMap contributors' url={darkMap?'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png':'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'}/>{mapMode==='balance'&&talukBoundary?<GeoJSON data={talukBoundary} style={feature=>{const s=talukStats[feature.properties.taluk];if(!s)return {color:'#91a7a7',weight:1,fillColor:'#dbe8e5',fillOpacity:.32};const shade=s.gap>8?COLORS.government:s.gap<-8?COLORS.private:COLORS.gold;return {color:'#fff',weight:selectedTaluk===feature.properties.taluk?3:1.2,fillColor:shade,fillOpacity:.28+Math.min(Math.abs(s.gap)/25,.55)};}} onEachFeature={(feature,layer)=>{const name=feature.properties.taluk,s=talukStats[name];layer.bindTooltip(s?name+' · '+s.gap.toFixed(1)+' pp bed-share gap':name+' · no matching facilities',{sticky:true});layer.on('click',()=>setSelectedTaluk(name));}}/>:mapBoundary&&<GeoJSON data={mapBoundary} style={{color:COLORS.government,weight:2,fillOpacity:0.025}}/>}
{mapMode==='density'?densityCells.map(c=><CircleMarker key={'cell-'+c.row+'-'+c.col} center={[c.lat,c.lon]} radius={Math.min(28,8+Math.sqrt(c.count)*5)} pathOptions={{color:c.private>=c.government&&c.private>=c.other?COLORS.private:c.government>c.private&&c.government>=c.other?COLORS.government:COLORS.purple,fillColor:c.private>c.government?COLORS.private:COLORS.government,fillOpacity:.2+.48*c.count/densityMax,weight:1.2}}><Popup><div className="map-popup"><strong>{c.count} facilities in this area</strong><span>{c.government} government · {c.private} private · {c.other} other</span><b>{fmt(c.beds)} listed beds</b></div></Popup></CircleMarker>):mapMode==='facilities'?filtered.filter(f=>Number.isFinite(Number(f.lat))&&Number.isFinite(Number(f.lon))).map(f=><CircleMarker key={String(f.id)+'-'+f.name} center={[Number(f.lat),Number(f.lon)]} radius={Math.max(5,Math.min(19,4+Math.sqrt(Number(f.beds)||0)/3.4))} pathOptions={{color:f.ownership==='Private'?COLORS.private:f.ownership==='Government'?COLORS.government:COLORS.purple,fillColor:f.ownership==='Private'?COLORS.private:COLORS.government,fillOpacity:.76,weight:1.5}} eventHandlers={{click:()=>setSelectedFacility(f)}}><Popup><div className="map-popup"><strong>{f.name}</strong><span>{f.type} · {f.taluk}</span><b>{fmt(f.beds)} listed beds</b><small>{f.ownership} · {f.address||'Address not available'}</small></div></Popup></CircleMarker>):null}</MapContainer></div><div className="map-footer"><span>{mapMode==='balance'?'Colour = bed share vs facility share.':mapMode==='density'?'Bubble size = locations.':'Size = beds · colour = owner.'}</span><button className="text-button" onClick={()=>setDarkMap(!darkMap)}>{darkMap?<Sun size={15}/>:<Moon size={15}/>} {darkMap?'Light map':'Dark map'}</button></div></section><aside className="side-panel"><div className="side-panel-heading"><h3>At a glance</h3><span className="tag">{fmt(filtered.length)} LOCATIONS</span></div><div className="map-stat-grid"><div><span>Facilities</span><b><CountUp value={filtered.length}/></b></div><div><span>Listed beds</span><b><CountUp value={bedTotal}/></b></div><div><span>Government</span><b><CountUp value={filtered.filter(f=>f.ownership==='Government').length}/></b></div><div><span>Private</span><b><CountUp value={filtered.filter(f=>f.ownership==='Private').length}/></b></div></div><div className="divider-line"/><h4>Facility footprint</h4><div className="map-rank-list">{topFacilityTaluks.length?topFacilityTaluks.map((t,i)=><button key={t.taluk} onClick={()=>{setTaluk(t.taluk);setSelectedTaluk(t.taluk);}}><span className="map-rank-copy"><span><i>{String(i+1).padStart(2,'0')}</i><b>{t.taluk}</b></span><em><i style={{width:Math.max(8,(t.facilities/(topFacilityTaluks[0]?.facilities||1))*100)+'%'}}/></em></span><strong>{t.facilities}</strong></button>):<p className="map-empty">No locations match these filters.</p>}</div>{selectedTaluk&&talukStats[selectedTaluk]&&<div className="selected-taluk"><span className="eyebrow">SELECTED TALUK</span><h4>{selectedTaluk}</h4><div><b>{talukStats[selectedTaluk].facilities}</b><span>facilities</span><b>{fmt(talukStats[selectedTaluk].beds)}</b><span>listed beds</span></div><small>{talukStats[selectedTaluk].gap>0?'Bed share exceeds facility share':talukStats[selectedTaluk].gap<0?'Facility share exceeds bed share':'Shares are aligned'} · {Math.abs(talukStats[selectedTaluk].gap).toFixed(1)} pp gap</small></div>}{selectedFacility&&<div className="selected-facility"><span className="eyebrow">SELECTED FACILITY</span><h4>{selectedFacility.name}</h4><p>{selectedFacility.type} · {selectedFacility.taluk}</p><div><b>{fmt(selectedFacility.beds)}</b><span>listed beds</span></div><small>{selectedFacility.address||'Address not available'}</small></div>}</aside></div>
        <section className="map-story-conclusion"><div className="map-conclusion-title"><span>MAP TAKEAWAY</span><h2>{filtered.length?(!largestShareGap?'Facilities appear across the selected taluks.':Math.abs(largestShareGap.gap)<0.05?'Facility and bed shares align in this view.':'Facility and bed shares differ by taluk.'):'No locations match these filters.'}</h2></div><div className="map-conclusion-evidence"><div><span>Most listed facilities</span><b>{leadingFacilityTaluk?.taluk||'—'}</b><small>{leadingFacilityTaluk?fmt(leadingFacilityTaluk.facilities)+' locations':'No result'}</small></div><div><span>Largest share difference</span><b>{largestShareGap?.taluk||'—'}</b><small>{largestShareGap?(largestShareGap.gap>0?'+':'')+largestShareGap.gap.toFixed(1)+' percentage points':'No comparison available'}</small></div></div><div className="map-conclusion-plan"><span>PLANNING OPTION</span><h3>Assess higher-level capacity beyond Udupi town.</h3><p>Compare population, travel and staffing before planning.</p><small></small></div></section>
      </>}
      {page==='graphs'&&<>
        <section className="story-hero">
          <div className="story-hero-copy"><span className="story-kicker"><span className="story-pulse"/> UDUPI DISTRICT · HEALTHCARE STORY</span><h1>Beyond facilities,<br/><em>into the health story.</em></h1><p>Follow the district story from outpatient demand and prevention to screenings, diagnostics and the care network.</p><div className="story-hero-actions"><button className="story-primary" onClick={()=>document.getElementById('story-locations')?.scrollIntoView({behavior:'smooth'})}>Explore the graphs <ChevronRight size={17}/></button><span className="story-hint">Scroll to discover the findings</span></div></div>
          <div className="story-orbit-art"><div className="story-orbit-ring ring-one"/><div className="story-orbit-ring ring-two"/><div className="story-orbit-core"><Activity size={34}/><b>UDUPI</b><small>HEALTH DATA</small></div><span className="orbit-label orbit-label-a">{fmt(filtered.length)}<small>facilities</small></span><span className="orbit-label orbit-label-b">{latestOPD===null?'—':fmt(latestOPD)}<small>outpatient visits</small></span><span className="orbit-label orbit-label-c">{talukData.length}<small>taluks</small></span></div>
          <div className="story-scroll-mark"><span/> THE STORY BEGINS</div>
        </section>
        <section className="story-kpis"><div><span>Outpatient visits</span><strong><CountUp value={latestOPD||0}/></strong><small>Allopathic attendance · {latestYear}</small></div><div><span>Children screened</span><strong><CountUp value={latestScreening}/></strong><small>Two RBSK age groups · {latestYear}</small></div><div><span>Immunization sessions held</span><strong>{latestSessionRate===null?'—':<CountUp value={latestSessionRate.toFixed(1)+'%'}/>}</strong><small>Of planned sessions · {latestYear}</small></div><div><span>Years of health records</span><strong><CountUp value={years.length}/></strong><small>{fmt(metricNames.length)} reported indicators</small></div></section>
        <section className="story-section" id="story-locations"><div className="story-section-heading"><span>01 / THE CARE NETWORK</span><h2>Where are facilities located?</h2><p>Start with the footprint of care, then explore the services recorded inside it.</p></div>
          <FilterBar taluks={taluks} types={types} taluk={taluk} setTaluk={setTaluk} ownership={ownership} setOwnership={setOwnership} facilityType={facilityType} setFacilityType={setFacilityType} search={search} setSearch={setSearch} reset={()=>{setTaluk('all');setOwnership('all');setFacilityType('all');setSearch('');}}/>
          <div className="story-chart-grid"><ChartCard title="Facilities by taluk" subtitle="How many listed locations appear in each area?" tag="FACILITY COUNT" wide><div className="story-chart"><ResponsiveContainer width="100%" height={350}><BarChart data={[...talukData].sort((a,b)=>a.facilities-b.facilities)} layout="vertical" margin={{left:12,right:35,top:8,bottom:8}}><CartesianGrid strokeDasharray="3 5" horizontal={false}/><XAxis type="number" axisLine={false} tickLine={false}/><YAxis type="category" dataKey="taluk" width={105} axisLine={false} tickLine={false} tick={{fontSize:12}}/><Tooltip formatter={(v)=>[fmt(v),'Facilities']}/><Bar dataKey="facilities" fill={COLORS.government} radius={[0,8,8,0]} maxBarSize={24} animationDuration={900}/></BarChart></ResponsiveContainer></div></ChartCard>
          <ChartCard title="Who runs the facilities?" subtitle="Share of all locations in view." tag="OWNERSHIP"><div className="story-chart ownership-donut"><ResponsiveContainer width="100%" height={245}><PieChart><Pie data={ownershipData} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius="61%" outerRadius="84%" paddingAngle={3} stroke="none" animationDuration={950}>{ownershipData.map(d=><Cell key={d.name} fill={d.color}/>)}</Pie><Tooltip formatter={(v,n)=>[fmt(v)+' facilities',n]}/><text x="50%" y="47%" textAnchor="middle" className="ownership-center-total">{fmt(filtered.length)}</text><text x="50%" y="57%" textAnchor="middle" className="ownership-center-label">locations</text></PieChart></ResponsiveContainer></div><div className="owner-share-list">{ownershipData.map(item=><div className="owner-share-row" key={item.name}><i style={{background:item.color}}/><b>{item.name}</b><strong>{filtered.length?(item.value/filtered.length*100).toFixed(1):'0.0'}%</strong><small>{fmt(item.value)}</small></div>)}</div></ChartCard><ChartCard title="Where are facility types?" subtitle="Colour shows type. Select a point for details." tag="FACILITY MAP"><div className="facility-type-map"><MapContainer center={[13.45,74.78]} zoom={9} minZoom={8} maxZoom={14} scrollWheelZoom={false} className="facility-type-leaflet"><TileLayer attribution='&copy; OpenStreetMap contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>{filtered.filter(f=>Number.isFinite(Number(f.lat))&&Number.isFinite(Number(f.lon))).map(f=><CircleMarker key={String(f.id)+'-'+f.name} center={[Number(f.lat),Number(f.lon)]} radius={7} pathOptions={{color:'#fff',fillColor:facilityTypeColors[safe(f.type)]||COLORS.ink,fillOpacity:.88,weight:1.5}}><Popup><div className="map-popup"><strong>{f.name}</strong><span>{safe(f.type)}</span><small>{safe(f.taluk)} · {safe(f.ownership)}</small></div></Popup></CircleMarker>)}</MapContainer>{!filtered.some(f=>Number.isFinite(Number(f.lat))&&Number.isFinite(Number(f.lon)))&&<div className="facility-map-empty">No mapped facilities in this view</div>}</div><div className="type-map-legend">{activeFacilityTypes.map(type=><span key={type}><i style={{background:facilityTypeColors[type]}}/>{type}</span>)}</div></ChartCard>
          </div>
        </section>
        <section className="story-section story-programs" id="story-programs"><div className="story-section-heading"><span>02 / SERVICES IN MOTION</span><h2>What care is being delivered?</h2><p>Outpatient · prevention · diagnostics</p></div><div className="story-chart-grid">
          <ChartCard title="Outpatient visits, by service" subtitle={'Reported visits in '+latestYear+'; each block represents a different service category.'} tag="SERVICE MIX" wide><div className="story-chart"><ResponsiveContainer width="100%" height={320}><Treemap data={outpatientMix} dataKey="value" aspectRatio={4/2.2} stroke="#fff" content={({x,y,width,height,name,value,index})=><g><rect x={x} y={y} width={width} height={height} rx={8} fill={[COLORS.government,COLORS.private,COLORS.aqua,COLORS.gold,COLORS.purple][(index||0)%5]} stroke="#fff" strokeWidth={3}/>{width>74&&height>42&&<><text x={x+10} y={y+23} fill="#fff" fontSize="12" fontWeight="700">{String(name).length>18?String(name).slice(0,17)+'…':name}</text>{height>66&&<text x={x+10} y={y+43} fill="#fff" fontSize="11">{fmt(value)} visits</text>}</>}</g>}><Tooltip formatter={(value)=>[fmt(value),'Reported visits']}/></Treemap></ResponsiveContainer></div></ChartCard>
          <ChartCard title="Chronic-care visits over time" subtitle="Yearly visits" tag="SERVICE TREND" wide><div className="story-chart"><ResponsiveContainer width="100%" height={310}><LineChart data={outpatientTrend} margin={{left:8,right:18,top:12,bottom:8}}><CartesianGrid strokeDasharray="3 5"/><XAxis dataKey="year" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false} tickFormatter={v=>fmt(v)}/><Tooltip formatter={v=>[fmt(v),'Reported visits']}/><Legend verticalAlign="top" height={28}/><Line type="monotone" dataKey="hypertension" name="Hypertension" stroke={COLORS.government} strokeWidth={3} connectNulls dot={{r:3}} animationDuration={900}/><Line type="monotone" dataKey="diabetes" name="Diabetes" stroke={COLORS.private} strokeWidth={3} connectNulls dot={{r:3}} animationDuration={900}/><Line type="monotone" dataKey="mental" name="Mental health" stroke={COLORS.purple} strokeWidth={3} connectNulls dot={{r:3}} animationDuration={900}/></LineChart></ResponsiveContainer></div></ChartCard>
          <ChartCard title="Immunization sessions: planned and held" subtitle="Delivery activity and the share of planned sessions held." tag="PREVENTION"><div className="story-chart"><ResponsiveContainer width="100%" height={290}><ComposedChart data={sessionTrend} margin={{left:4,right:6,top:16,bottom:8}}><CartesianGrid strokeDasharray="3 5" vertical={false}/><XAxis dataKey="year" axisLine={false} tickLine={false}/><YAxis yAxisId="sessions" axisLine={false} tickLine={false}/><YAxis yAxisId="rate" orientation="right" domain={[0,100]} tickFormatter={v=>v+'%'} axisLine={false} tickLine={false}/><Tooltip formatter={(v,key)=>key==='completion'?[Number(v).toFixed(1)+'%','Planned sessions held']:[fmt(v),key==='planned'?'Sessions planned':'Sessions held']}/><Legend verticalAlign="top" height={28}/><Bar yAxisId="sessions" dataKey="planned" name="Planned" fill={COLORS.aqua} radius={[5,5,0,0]}/><Bar yAxisId="sessions" dataKey="held" name="Held" fill={COLORS.government} radius={[5,5,0,0]}/><Line yAxisId="rate" dataKey="completion" name="Share held" stroke={COLORS.private} strokeWidth={3} dot={{r:3}} connectNulls animationDuration={850}/></ComposedChart></ResponsiveContainer></div></ChartCard>
          <ChartCard title="Child screening reach by age group" subtitle="Yearly screenings" tag="OUTREACH"><div className="story-chart"><ResponsiveContainer width="100%" height={290}><AreaChart data={screeningTrend} margin={{left:4,right:10,top:14,bottom:8}}><defs><linearGradient id="youngScreenFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={COLORS.aqua} stopOpacity={0.5}/><stop offset="100%" stopColor={COLORS.aqua} stopOpacity={0.04}/></linearGradient><linearGradient id="schoolScreenFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={COLORS.private} stopOpacity={0.33}/><stop offset="100%" stopColor={COLORS.private} stopOpacity={0.03}/></linearGradient></defs><CartesianGrid strokeDasharray="3 5"/><XAxis dataKey="year" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip formatter={v=>[fmt(v),'Screenings recorded']}/><Legend verticalAlign="top" height={28}/><Area type="monotone" dataKey="young" name="6 months–6 years" stroke={COLORS.government} fill="url(#youngScreenFill)" connectNulls animationDuration={850}/><Area type="monotone" dataKey="school" name="6–18 years" stroke={COLORS.private} fill="url(#schoolScreenFill)" connectNulls animationDuration={850}/></AreaChart></ResponsiveContainer></div></ChartCard>
          <ChartCard title="Maternal support services" subtitle={'Reported program outputs in '+latestYear+'.'} tag="MATERNAL HEALTH"><div className="story-chart"><ResponsiveContainer width="100%" height={290}><BarChart data={maternalSupport} layout="vertical" margin={{left:16,right:24,top:8,bottom:8}}><CartesianGrid strokeDasharray="3 5" horizontal={false}/><XAxis type="number" axisLine={false} tickLine={false}/><YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={{fontSize:10}}/><Tooltip formatter={v=>[fmt(v),'Reported services']}/><Bar dataKey="value" name="Reported services" fill={COLORS.purple} radius={[0,7,7,0]} maxBarSize={23} animationDuration={850}/></BarChart></ResponsiveContainer></div></ChartCard>
          <ChartCard title="Diagnostics: total tests and Hb share" subtitle="Yearly test volumes" tag="DIAGNOSTICS"><div className="story-chart"><ResponsiveContainer width="100%" height={290}><ComposedChart data={labTrend.map(d=>({...d,hbShare:d.labs>0&&d.hb!==null?d.hb/d.labs*100:null}))} margin={{left:4,right:8,top:14,bottom:8}}><CartesianGrid strokeDasharray="3 5" vertical={false}/><XAxis dataKey="year" axisLine={false} tickLine={false}/><YAxis yAxisId="tests" axisLine={false} tickLine={false} tickFormatter={v=>fmt(v)}/><YAxis yAxisId="share" orientation="right" domain={[0,100]} tickFormatter={v=>v+'%'}/><Tooltip formatter={(v,key)=>key==='hbShare'?[Number(v).toFixed(1)+'%','Hb tests / all lab tests']:[fmt(v),key==='labs'?'All lab tests':'Hb tests']}/><Legend verticalAlign="top" height={28}/><Bar yAxisId="tests" dataKey="labs" name="All lab tests" fill={COLORS.aqua} radius={[5,5,0,0]}/><Line yAxisId="tests" dataKey="hb" name="Hb tests" stroke={COLORS.government} strokeWidth={2.5} dot={false} connectNulls/><Line yAxisId="share" dataKey="hbShare" name="Hb share" stroke={COLORS.private} strokeWidth={3} dot={{r:3}} connectNulls/></ComposedChart></ResponsiveContainer></div></ChartCard>
          <ChartCard title="Emergency activity: indexed change" subtitle="Each line starts at its first reported year." tag="ACUTE CARE" wide><div className="story-chart"><ResponsiveContainer width="100%" height={300}><LineChart data={emergencyIndex} margin={{left:8,right:18,top:10,bottom:8}}><CartesianGrid strokeDasharray="3 5"/><XAxis dataKey="year" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false} tickFormatter={v=>v}/><Tooltip formatter={v=>[Number(v).toFixed(0),'Index (first reported year = 100)']}/><Legend verticalAlign="top" height={28}/>{emergencySeries.map(series=><Line key={series.label} type="monotone" dataKey={series.label} name={series.label} stroke={series.color} strokeWidth={2.5} connectNulls dot={false} activeDot={{r:5}} animationDuration={900}/>)}</LineChart></ResponsiveContainer></div></ChartCard>
        </div></section>
        <section className="story-section story-tint" id="story-capacity"><div className="story-section-heading"><span>03 / FACILITY CAPACITY</span><h2>How do listed beds compare with facility locations?</h2><p>Capacity distribution is one part of the district story; service activity adds the wider context.</p></div><div className="story-chart-grid">
          <ChartCard title="Bed share versus facility share" subtitle="Bed share compared with facility share." tag="CAPACITY BALANCE" wide><div className="story-chart"><ResponsiveContainer width="100%" height={330}><BarChart data={capacityBalance} layout="vertical" margin={{left:12,right:32,top:8,bottom:8}}><CartesianGrid strokeDasharray="3 5" horizontal={false}/><XAxis type="number" domain={[-balanceExtent,balanceExtent]} tickFormatter={v=>v+' pp'} axisLine={false} tickLine={false}/><YAxis type="category" dataKey="taluk" width={105} axisLine={false} tickLine={false} tick={{fontSize:12}}/><ReferenceLine x={0} stroke="#81999a"/><Tooltip formatter={v=>[Number(v).toFixed(1)+' percentage points','Bed share minus facility share']}/><Bar dataKey="gap" name="Share gap" radius={[7,7,7,7]} maxBarSize={22} animationDuration={900}>{capacityBalance.map(t=><Cell key={t.taluk} fill={t.gap>=0?COLORS.government:COLORS.private}/>)}</Bar></BarChart></ResponsiveContainer></div></ChartCard>
        </div></section>        <section className="story-section" id="story-trends"><div className="story-section-heading"><span>03 / CHANGE OVER TIME</span><h2>What changed over time?</h2><p>Explore recorded district indicators over time.</p></div><div className="story-trend-panel"><div className="story-trend-controls"><label>Choose an indicator<select value={metric} onChange={e=>{setMetric(e.target.value);setYearIndex(Math.max(0,years.length-1));}}>{metricNames.map(name=><option key={name} value={name}>{name}</option>)}</select></label><div className="story-year-control"><span>Year</span><strong>{currentTrend?.year||years[yearIndex]||'—'}</strong><button onClick={()=>setPlaying(!playing)} className="story-play-button">{playing?<Pause size={16}/>:<Play size={16}/>} {playing?'Pause':'Play timeline'}</button></div></div><div className="story-big-number">{currentTrend?.value==null?'No value recorded':fmt(currentTrend.value)}<small>{currentTrend?.records?`${currentTrend.records} monthly records`: 'Recorded indicator value'}</small></div><div className="story-chart story-trend-chart"><ResponsiveContainer width="100%" height={330}><AreaChart data={trendData.filter(d=>d.value!==null)} margin={{left:5,right:18,top:15,bottom:8}}><defs><linearGradient id="storyTrendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={COLORS.aqua} stopOpacity={0.55}/><stop offset="100%" stopColor={COLORS.aqua} stopOpacity={0.03}/></linearGradient></defs><CartesianGrid strokeDasharray="3 5"/><XAxis dataKey="year" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>[fmt(v),'Recorded value']}/><Area type="monotone" dataKey="value" stroke={COLORS.government} strokeWidth={3} fill="url(#storyTrendFill)" activeDot={{r:6}} animationDuration={800}/></AreaChart></ResponsiveContainer></div><div className="story-timeline"><button aria-label="Previous year" onClick={()=>{setPlaying(false);setYearIndex(i=>Math.max(0,i-1));}}>−</button><input aria-label="Timeline year" type="range" min="0" max={Math.max(0,years.length-1)} value={yearIndex} onChange={e=>{setPlaying(false);setYearIndex(Number(e.target.value));}}/><button aria-label="Next year" onClick={()=>{setPlaying(false);setYearIndex(i=>Math.min(years.length-1,i+1));}}>+</button><span>{years[0]} — {years[years.length-1]}</span></div><p className="story-caption">Values come from the supplied historical records. Missing years are not treated as zero.</p></div>
          <section className="reporting-coverage"><div className="coverage-heading"><span>DATA COMPLETENESS</span><h3>How complete is this indicator by year?</h3><p>Months with records for the selected indicator. Missing months are left unfilled.</p></div><div className="coverage-grid">{years.map(y=>{const months=Math.min(12,Number(history[metric]?.[y]?.months)||0);return <div className="coverage-year" key={y} title={y+": "+months+" of 12 months"}><div className="coverage-track"><i style={{height:(Math.max(0,months)/12*100)+"%"}}/></div><small>{y.slice(2)}</small><b>{months?months+"/12":"—"}</b></div>;})}</div></section><div className="story-mini-trends"><div className="story-mini-heading"><span>MORE TO EXPLORE</span><h3>Choose another health indicator</h3><p>These indicators can help you ask different questions about health services over time.</p></div><div className="story-indicator-grid">{metricNames.filter(name=>name!==metric).slice(0,6).map((name,i)=>{const vals=years.map(y=>history[name]?.[y]?.value).filter(v=>v!==null&&v!==undefined&&Number.isFinite(Number(v)));const latest=vals.length?vals[vals.length-1]:null;const first=vals.length?vals[0]:null;const change=first!==null&&first!==0&&latest!==null?((latest-first)/Math.abs(first))*100:null;return <button key={name} className="story-indicator-card" onClick={()=>{setMetric(name);setYearIndex(Math.max(0,years.length-1));document.getElementById('story-trends')?.scrollIntoView({behavior:'smooth'});}}><span>INDICATOR {String(i+1).padStart(2,'0')}</span><b>{name}</b><strong>{latest==null?'—':fmt(latest)}</strong><small>{change===null?'Change not available':`${change>=0?'↑':'↓'} ${Math.abs(change).toFixed(1)}% from first to latest available record`}</small></button>;})}</div></div>
        </section>
        <section className="story-section story-tint" id="story-findings"><div className="story-section-heading"><span>04 / WHAT STANDS OUT</span><h2>What the indicators reveal.</h2><p>A few patterns worth exploring further, based on the supplied data.</p></div><div className="story-insight-grid">{[{n:'01',title:'Outpatient demand',body:latestOPD===null?'No allopathic attendance value is available for the latest year.':'The district recorded '+fmt(latestOPD)+' allopathic outpatient visits in '+latestYear+'.',value:latestOPD===null?'—':fmt(latestOPD),label:'reported visits · latest year'},{n:'02',title:'Child screening',body:fmt(latestScreening)+' screenings were recorded across two RBSK age groups in '+latestYear+'.',value:fmt(latestScreening),label:'screenings recorded'},{n:'03',title:'Immunization delivery',body:latestSessionRate===null?'No plan-versus-held comparison is available for the latest year.':latestSessionRate.toFixed(1)+'% of planned sessions were reported as held in '+latestYear+'.',value:latestSessionRate===null?'—':latestSessionRate.toFixed(1)+'%',label:'of planned sessions held'},{n:'04',title:'Most reported outpatient category',body:outpatientMix[0]?outpatientMix[0].name+' has the highest recorded service count in '+latestYear+'.':'No outpatient category values are available.',value:outpatientMix[0]?fmt(outpatientMix[0].value):'—',label:'reported visits · latest year'},{n:'05',title:'Historical record',body:'The supplied health history contains '+fmt(metricNames.length)+' indicators across '+years.length+' fiscal years.',value:fmt(years.length),label:'fiscal years available'},{n:'06',title:'Interpret with context',body:'Counts show reported activity. They do not establish population coverage, service quality or unmet need.',value:'Context',label:'counts are not rates'}].map(item=><article key={item.n} className="story-insight-card"><span>{item.n}</span><div><h3>{item.title}</h3><p>{item.body}</p><strong><CountUp value={item.value}/></strong><small>{item.label}</small></div></article>)}</div></section>
        <section className="story-section story-recommendations" id="story-recommendations"><div className="story-section-heading"><span>05 / PLANNING OPTIONS</span><h2>Questions for the next plan</h2><p>Planning ideas</p></div><div className="story-recommendation-grid"><article className="priority-card"><span>01</span><h3>Assess a larger hospital beyond Udupi town</h3><p>Model population served, referral demand, travel time, staffing and operating cost.</p></article><article><span>02</span><h3>Measure access to beds</h3><p>Compare bed supply with population, occupancy and travel time by taluk.</p></article><article><span>03</span><h3>Strengthen referral links</h3><p>Review services, staffing and transfers between taluks before adding capacity.</p></article></div></section>
        <section className="story-conclusion"><div className="story-conclusion-art"><div className="story-conclusion-ring"><Activity size={34}/></div></div><div><span>THE TAKEAWAY</span><h2>Better questions<br/>start with clearer data.</h2><p>Explore Udupi facilities, services and trends. Add local population and travel data for the full picture.</p><div className="story-conclusion-actions"><button className="story-primary" onClick={()=>navTo('findings')}>Read the findings <ChevronRight size={16}/></button><button className="story-secondary" onClick={()=>navTo('map')}>Return to map</button></div></div></section>
        <section className="graph-next-step"><div><span className="eyebrow">YOUR OWN DATA</span><h2>Want to explore an Excel file?</h2><p>Build a chart from your own spreadsheet columns.</p></div><button className="button primary" onClick={()=>navTo('upload')}>Open Excel tools <ChevronRight size={16}/></button></section>
      </>}
      {page==='upload'&&<>
        <PageIntro eyebrow="UPLOAD" title="Add a dataset" subtitle="Upload a facility file." source={sourceLabel}/>
        <div className="upload-layout"><section className="upload-card"><div className="upload-icon"><Upload size={25}/></div><h2>Upload healthcare facilities</h2><p>Use the template to make sure the column names and coordinates are recognised.</p><label className="dropzone" htmlFor="dataset-file"><input id="dataset-file" type="file" accept=".csv,.xlsx,.xls" onChange={e=>{uploadFile(e.target.files?.[0]);e.target.value='';}}/><span className="dropzone-icon"><FileSpreadsheet size={28}/></span><b>{busy?'Processing your file…':'Choose an Excel or CSV file'}</b><small>CSV, XLSX or XLS · Maximum 15 MB</small><span className="button primary">Browse files</span></label>{uploadError&&<div className="alert error"><AlertCircle size={17}/><span>{uploadError}</span></div>}{uploadSuccess&&<div className="alert success"><CheckCircle2 size={17}/><span>{uploadSuccess}</span></div>}<div className="upload-actions"><button className="button secondary" onClick={downloadTemplate}><Download size={16}/> Download Excel template</button><button className="button text-button" disabled={busy} onClick={resetDataset}><RotateCcw size={16}/> Restore original sample</button></div></section><aside className="requirements-card"><span className="eyebrow">REQUIRED COLUMNS</span><h3>What your file needs</h3><p>Column matching is case-insensitive and supports common aliases.</p><ul className="required-list"><li><CheckCircle2 size={17}/><span><b>name</b><small>Facility or hospital name</small></span><span className="required-tag">Required</span></li><li><CheckCircle2 size={17}/><span><b>lat, lon</b><small>Geographic coordinates</small></span><span className="required-tag">Required</span></li><li><CheckCircle2 size={17}/><span><b>beds</b><small>Non-negative bed capacity</small></span><span className="optional-tag">Recommended</span></li><li><CheckCircle2 size={17}/><span><b>ownership</b><small>Government, Private or another label</small></span><span className="optional-tag">Recommended</span></li><li><CheckCircle2 size={17}/><span><b>taluk, type, address</b><small>Area and facility details</small></span><span className="optional-tag">Optional</span></li></ul><div className="notice"><AlertCircle size={17}/><p>Each row needs a facility name and valid latitude/longitude for mapping. A successful upload replaces the active facility list; the original historical indicator series remains available.</p></div></aside></div>
        <section className="after-upload"><div><h3>Explore the active dataset</h3><p>After a successful facility upload, continue to the map or healthcare graph story.</p></div><div className="hero-actions"><button className="button primary" onClick={()=>navTo('map')}>Open in Map <MapIcon size={16}/></button><button className="button secondary" onClick={()=>navTo('graphs')}>Open in Graphs <ChartNoAxesColumn size={16}/></button></div></section>
        <section className="excel-visualizer"><div className="visualizer-intro"><span className="eyebrow">DYNAMIC EXCEL VISUALIZATION</span><h2>Bring any spreadsheet to life.</h2><p>Upload a CSV or Excel file, select the columns to compare, and switch chart types. This preview is separate from the facility dataset until you choose to upload it above.</p><label className="button primary excel-pick" htmlFor="visualizer-file"><FileSpreadsheet size={17}/> Choose Excel or CSV<input id="visualizer-file" type="file" accept=".csv,.xlsx,.xls" onChange={e=>{loadExcelForVisualisation(e.target.files?.[0]);e.target.value='';}}/></label>{excelFileName&&<span className="file-loaded"><CheckCircle2 size={15}/>{excelFileName} · {fmt(excelRows.length)} rows loaded</span>}{excelError&&<div className="alert error"><AlertCircle size={16}/>{excelError}</div>}</div>
        {excelRows.length>0&&<><div className="visualizer-controls"><label className="field-label">Group / X-axis<select value={excelX} onChange={e=>setExcelX(e.target.value)}>{excelHeaders.map(h=><option key={h} value={h}>{h}</option>)}</select></label><label className="field-label">Numeric measure / Y-axis<select value={excelY} onChange={e=>setExcelY(e.target.value)}>{excelHeaders.map(h=><option key={h} value={h}>{h}</option>)}</select></label><label className="field-label">Visualization type<select value={excelChartType} onChange={e=>setExcelChartType(e.target.value)}><option value="bar">Bar chart</option><option value="line">Line chart</option><option value="area">Area chart</option><option value="scatter">Scatter chart</option></select></label></div><div className="excel-preview-grid"><ChartCard title={`${excelY} by ${excelX}`} subtitle={`Averages numeric values for repeated ${excelX} labels; showing up to 60 groups`} tag={excelChartType.toUpperCase()} wide>{excelChartData.length===0?<div className="empty-chart">No numeric values found in the selected measure. Choose a numeric column for the Y-axis.</div>:<ResponsiveContainer width="100%" height={350}>{excelChartType==='line'?<LineChart data={excelChartData} margin={{top:10,right:20,left:5,bottom:50}}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="label" angle={-22} textAnchor="end" interval={0} height={75} tick={{fontSize:11}}/><YAxis/><Tooltip/><Line type="monotone" dataKey="value" name={excelY} stroke={COLORS.government} strokeWidth={3} activeDot={{r:5}}/></LineChart>:excelChartType==='area'?<AreaChart data={excelChartData} margin={{top:10,right:20,left:5,bottom:50}}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="label" angle={-22} textAnchor="end" interval={0} height={75} tick={{fontSize:11}}/><YAxis/><Tooltip/><Area type="monotone" dataKey="value" name={excelY} stroke={COLORS.government} fill={COLORS.aqua} fillOpacity={0.35}/></AreaChart>:excelChartType==='scatter'?<ScatterChart margin={{top:10,right:20,left:5,bottom:35}}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="rowIndex" name="Row number" type="number"/><YAxis dataKey="value" name={excelY} type="number"/><ZAxis range={[45,130]}/><Tooltip cursor={{strokeDasharray:'3 3'}}/><Scatter data={excelChartData.map((d,i)=>({...d,rowIndex:i+1}))} fill={COLORS.private}/></ScatterChart>:<BarChart data={excelChartData} margin={{top:10,right:20,left:5,bottom:50}}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="label" angle={-22} textAnchor="end" interval={0} height={75} tick={{fontSize:11}}/><YAxis/><Tooltip/><Bar dataKey="value" name={excelY} fill={COLORS.government} radius={[5,5,0,0]}/></BarChart>}</ResponsiveContainer>}</ChartCard><section className="excel-data-preview"><div className="chart-card-head"><div><h3>Data preview</h3><p>First five rows from the selected worksheet</p></div><span className="tag">{excelHeaders.length} COLUMNS</span></div><div className="table-scroll"><table><thead><tr>{excelHeaders.slice(0,8).map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{excelRows.slice(0,5).map((row,i)=><tr key={i}>{excelHeaders.slice(0,8).map(h=><td key={h}>{String(row[h]??'')}</td>)}</tr>)}</tbody></table></div></section></div></>}
        </section>
      </>}
      {page==='findings'&&<>
        <PageIntro eyebrow="FINDINGS" title="Udupi at a glance" subtitle="" source={sourceLabel}/>
        <section className="findings-kpis"><div><span>Outpatient visits</span><b>{latestOPD===null?'—':fmt(latestOPD)}</b><small>{latestYear}</small></div><div><span>Children screened</span><b>{fmt(latestScreening)}</b><small>{latestYear}</small></div><div><span>Immunization sessions</span><b>{latestSessionRate===null?'—':latestSessionRate.toFixed(1)+'%'}</b><small>planned sessions held</small></div><div><span>Facilities</span><b>{fmt(filtered.length)}</b><small>{talukData.length} taluks</small></div></section>
        <div className="findings-grid compact-findings"><article className="finding-card"><span className="finding-index">01</span><div><h3>Largest facility footprint</h3><p>{leadingFacilityTaluk?leadingFacilityTaluk.taluk+' · '+fmt(leadingFacilityTaluk.facilities)+' locations':'No facilities match'}</p></div></article><article className="finding-card"><span className="finding-index">02</span><div><h3>Bed-share difference</h3><p>{largestShareGap?largestShareGap.taluk+' · '+Math.abs(largestShareGap.gap).toFixed(1)+' pp':'No bed data'}</p></div></article><article className="finding-card"><span className="finding-index">03</span><div><h3>Health history</h3><p>{fmt(metricNames.length)} indicators · {years.length} years</p></div></article></div>
        <section className="recommendation-panel concise-recommendations"><div className="recommendation-heading"><span className="eyebrow light">NEXT STEPS</span><h2>Planning ideas</h2></div><div className="recommendation-list"><Recommendation n="01" title="Check access by taluk" text="Compare travel times and population."/><Recommendation n="02" title="Review staffing" text="Map services and referral routes."/><Recommendation n="03" title="Update facility records" text="Confirm locations and bed counts."/></div></section>
        <section className="conclusion-panel"><div className="conclusion-mark"><Activity size={22}/></div><div><span className="eyebrow">TAKEAWAY</span><h2>Plan for access, not just counts.</h2><p>Compare population, travel time and services before adding capacity.</p></div><button className="button primary" onClick={()=>navTo('map')}>Open map <MapIcon size={16}/></button></section>      </>}
    </main>
    <footer className="app-footer"><div className="footer-brand"><span className="brand-mark"><Activity size={16}/></span><span>Arogya Insights</span></div><span>Udupi health</span></footer>
  </div>;
}

function CountUp({value}) { const raw=String(value??""); const match=raw.match(/^([^0-9-]*)(-?\d[\d,]*(?:\.\d+)?)(.*)$/); const target=match?Number(match[2].replace(/,/g,"")):NaN; const decimals=match?.[2].split(".")[1]?.length||0; const [shown,setShown]=useState(0); useEffect(()=>{if(!Number.isFinite(target))return; if(window.matchMedia?.("(prefers-reduced-motion: reduce)").matches){setShown(target);return;} let start=null; let frame; const tick=t=>{if(start===null)start=t; const p=Math.min(1,(t-start)/850); setShown(target*(1-Math.pow(1-p,3))); if(p<1)frame=requestAnimationFrame(tick);}; frame=requestAnimationFrame(tick); return()=>cancelAnimationFrame(frame);},[target]); if(!Number.isFinite(target))return raw; return <>{match[1]}{shown.toLocaleString("en-IN",{minimumFractionDigits:decimals,maximumFractionDigits:decimals})}{match[3]}</>; }
function Stat({icon:Icon,label,value,note}) { return <article className="stat-card"><span className="stat-icon"><Icon size={20}/></span><span className="stat-label">{label}</span><strong><CountUp value={value}/></strong><small>{note}</small></article>; }
function Feature({icon:Icon,number,title,text,action,onClick}) { return <button className="feature-card" onClick={onClick}><div className="feature-top"><span className="feature-icon"><Icon size={22}/></span><span className="feature-number">{number}</span></div><h3>{title}</h3><p>{text}</p><span className="feature-action">{action}<ChevronRight size={16}/></span></button>; }
function PageIntro({eyebrow,title,subtitle,source}) { return <section className="page-intro"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div><span className="source-pill"><span className="status-dot"/>{source}</span></section>; }
function FilterBar({taluks,types,taluk,setTaluk,ownership,setOwnership,facilityType,setFacilityType,search,setSearch,reset}) { return <section className="filter-bar"><div className="filter-title"><Filter size={17}/><span>Filter facilities</span></div><label>Taluk<select value={taluk} onChange={e=>setTaluk(e.target.value)}><option value="all">All taluks</option>{taluks.map(t=><option key={t}>{t}</option>)}</select></label><label>Ownership<select value={ownership} onChange={e=>setOwnership(e.target.value)}><option value="all">All providers</option><option value="Government">Government</option><option value="Private">Private</option></select></label><label>Facility type<select value={facilityType} onChange={e=>setFacilityType(e.target.value)}><option value="all">All facility types</option>{types.map(t=><option key={t}>{t}</option>)}</select></label><label className="search-filter"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search facility or area"/></label><button className="reset-filter" onClick={reset}><RotateCcw size={15}/> Reset</button></section>; }
function ChartCard({title,subtitle,tag,wide,children}) { return <article className={`chart-card ${wide?'wide':''}`}><div className="chart-card-head"><div><h3>{title}</h3><p>{subtitle}</p></div><span className="tag">{tag}</span></div>{children}</article>; }
function Insight({children}) { return <div className="insight-note"><span className="insight-mark"><Lightbulb size={16}/></span><p>{children}</p></div>; }
function Recommendation({n,title,text}) { return <article className="recommendation-row"><span>{n}</span><div><h3>{title}</h3><p>{text}</p></div></article>; }

createRoot(document.getElementById('root')).render(<App/>);
